do.cmd:
START=${START:-4}; END=${END:-55}
for i in $(seq "$START" "$END"); do
  printf '# v%s\n' "$i" > t.md
  agnes artifact update "$A" --base-version $((i-1)) --markdown t.md --note "e2e $i" > /dev/null && echo "ok v$i" || { echo "stopped at v$i"; break; }
done

